    # @attr.s
    # class B:
    #     y: int = attr.ib(type=str)

    @attr.s
    class B:
        y: int = attr.ib(type=str)

    print("REPRO PASS")
except ValueError as e:
    print(f"Caught expected error: {e}")
    if "Type annotation and type argument cannot both be present" in str(e):
        print("REPRO FAIL")
    else:
        print(f"Caught different ValueError: {e}")
except Exception as e:
    print(f"Caught unexpected exception: {type(e).__name__}: {e}")
EOF
