import attr

try:
    @attr.s
    class MyClass:
        x: int = attr.ib(type=int)
except ValueError as e:
    print(f"Caught expected error: {e}")
    assert "attribute 'x'" in str(e)
    print("Repro success: attribute name is in the error message")
else:
    print("Repro fail: ValueError not raised")
    exit(1)

